import demographySum from "@/data/demography/sum.json";
import demographyAge from "@/data/demography/age.json";
import demographyAgeMedian from "@/data/demography/age_median.json";

// Snapshots generated by `python3 -m api.demography.export_json`.
// Filtering mirrors `prep_output` in api/demography/utils.py.

type Row = {
  geo: string;
  full_name: string;
  year: number;
  value: number;
  eu: number;
  ce: number;
  age_from?: number;
  age_to?: number;
};

function filterRows(
  rows: Row[],
  country: string,
  year: string | number,
  region: string,
  age: string = "all"
): Row[] {
  return rows.filter((row) => {
    if (country !== "all" && row.geo !== country.toUpperCase()) return false;
    if (year !== "all" && row.year !== Number(year)) return false;
    if (region.toUpperCase() === "EU" && row.eu !== 1) return false;
    if (region.toUpperCase() === "CE" && row.ce !== 1) return false;
    if (
      age !== "all" &&
      row.age_from !== undefined &&
      row.age_to !== undefined &&
      !(row.age_from <= Number(age) && row.age_to >= Number(age))
    ) {
      return false;
    }
    return true;
  });
}

export async function getDemographySeries(
  country: string = "all",
  year: string | number = "all",
  region: string = "all"
) {
  return filterRows(demographySum, country, year, region).map(
    ({ geo, full_name, year, value }) => ({ geo, full_name, year, value })
  );
}

export async function getDemographyAgeSeries(
  country?: string,
  year?: string | number,
  region?: string,
  age?: "median"
): Promise<{ geo: string; full_name: string; year: number; value: number }[]>;
export async function getDemographyAgeSeries(
  country?: string,
  year?: string | number,
  region?: string,
  age?: string
): Promise<{ geo: string; full_name: string; year: number; value: number; age_from: number; age_to: number }[]>;
export async function getDemographyAgeSeries(
  country: string = "all",
  year: string | number = "all",
  region: string = "all",
  age: string = "all"
) {
  if (age === "median") {
    return filterRows(demographyAgeMedian, country, year, region).map(
      ({ geo, full_name, year, value }) => ({ geo, full_name, year, value })
    );
  }
  return filterRows(demographyAge, country, year, region, age).map(
    ({ geo, full_name, year, value, age_from, age_to }) => ({
      geo,
      full_name,
      year,
      value,
      age_from,
      age_to,
    })
  );
}
